/* ============================================================
   126_platplc : 대지위치(getApPlatPlcInfo)가 합필의 다리를 놓는가 (읽기 전용)
                 2026-10-18  녹번동(11380/10200) 전수 3899행

   ★ 가설: 재개발 허가의 대지위치에는 **합필 전 지번이 전부** 들어 있다.
     북한산 푸르지오(1,230세대) 허가 하나에 대지위치가 489개다.
     그렇다면 그 지번들 중 하나가 **지금 단지의 PNU** 와 맞을 수 있다.
     맞으면 `청약홈/인허가 지번 -> 대지위치 -> 허가 -> 단지` 다리가 놓인다.
   ★ 이 파일은 아무것도 안 바꾼다.
   ============================================================ */
USE Teomoony;
GO
SET NOCOUNT ON;
GO
IF OBJECT_ID('tempdb..#plat') IS NOT NULL DROP TABLE #plat;
CREATE TABLE #plat (pms_pk VARCHAR(30), bun CHAR(4), ji CHAR(4),
                    repr_yn CHAR(1), plat_gb CHAR(1));
GO
GO
GO
GO
GO
GO

PRINT '--- 1. 대지위치로 만든 PNU 가 단지에 붙나 (허가 단위) ---';
WITH p AS (
  SELECT pms_pk, bun, ji, repr_yn,
         pnu = meta.fn_make_pnu('11380','10200', plat_gb, bun, ji)
    FROM #plat),
j AS (
  SELECT p.pms_pk,
         지번수   = COUNT(*),
         붙은지번 = SUM(CASE WHEN EXISTS (SELECT 1 FROM gold.complex_pnu cp
                                           WHERE cp.pnu = p.pnu) THEN 1 ELSE 0 END),
         대표붙음 = MAX(CASE WHEN p.repr_yn='1' AND EXISTS (SELECT 1 FROM gold.complex_pnu cp
                                           WHERE cp.pnu = p.pnu) THEN 1 ELSE 0 END)
    FROM p GROUP BY p.pms_pk)
SELECT 구간 = CASE WHEN 지번수 = 1 THEN N'지번 1개'
                   WHEN 지번수 < 10 THEN N'지번 2~9개'
                   WHEN 지번수 < 100 THEN N'지번 10~99개'
                   ELSE N'지번 100개+' END,
       허가수 = COUNT(*),
       대표로붙음 = SUM(대표붙음),
       대표는안붙는데_다른지번으로붙음 = SUM(CASE WHEN 대표붙음=0 AND 붙은지번>0 THEN 1 ELSE 0 END),
       전혀안붙음 = SUM(CASE WHEN 붙은지번=0 THEN 1 ELSE 0 END)
  FROM j
 GROUP BY CASE WHEN 지번수 = 1 THEN N'지번 1개'
               WHEN 지번수 < 10 THEN N'지번 2~9개'
               WHEN 지번수 < 100 THEN N'지번 10~99개'
               ELSE N'지번 100개+' END
 ORDER BY 1;
PRINT '  ★ 가운데 칸이 이 다리의 값어치다 - 대표로는 못 붙는데 딴 지번으로 붙는 허가.';
GO

PRINT '--- 2. 북한산 푸르지오(1013100034638) 489개 중 붙는 지번 ---';
SELECT TOP 20 p.bun, p.ji, p.repr_yn,
       pnu = meta.fn_make_pnu('11380','10200', p.plat_gb, p.bun, p.ji),
       단지 = c.complex_nm, 세대 = c.hhld_cnt_sum
  FROM #plat p
  JOIN gold.complex_pnu cp ON cp.pnu = meta.fn_make_pnu('11380','10200', p.plat_gb, p.bun, p.ji)
  JOIN gold.complex c ON c.complex_id = cp.complex_id
 WHERE p.pms_pk = '1013100034638'
 ORDER BY c.hhld_cnt_sum DESC;
GO

PRINT '--- 3. 래미안 베라힐즈(1013100038039) 는 대지위치가 1개뿐이다. 그 단지는? ---';
SELECT c.complex_nm, cp.pnu, c.hhld_cnt_sum
  FROM gold.complex c JOIN gold.complex_pnu cp ON cp.complex_id=c.complex_id
 WHERE cp.pnu LIKE '1138010200%' AND c.hhld_cnt_sum >= 900
 ORDER BY c.hhld_cnt_sum DESC;
GO
